import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`stock-watchlist`,heroCta:`Track my watchlist`,heroTitle:`Track your watchlist`,heroSubtitle:`Perplexity Computer monitors analyst ratings, flags upgrades and downgrades, and delivers morning alerts automatically.`,inputUrlCta:`Track my watchlist`,inputUrlPlaceholder:`e.g. NVDA, AAPL, TSLA...`,inputUrlPrefill:`Go to {url} and extract every stock ticker listed. Then monitor analyst ratings from Goldman Sachs, Morgan Stanley, JP Morgan, Bank of America, Citi, UBS, Barclays, Deutsche Bank, Wells Fargo, Credit Suisse, Jefferies, and Raymond James. For each ticker: 1) Flag every upgrade and downgrade with the firm name, previous rating, new rating, and rationale. 2) Track price target changes and calculate the new consensus price target. 3) Identify any significant consensus shifts in the last 24 hours. 4) Deliver a formatted morning briefing summarizing all changes, sorted by magnitude of rating change, with links to source reports where available.`,heroOverlaySteps:[`Extracting tickers from your watchlist`,`Scanning analyst ratings from Goldman Sachs, Morgan Stanley, and 10 other firms`,`Flagging upgrades, downgrades, and price target changes with rationale`,`Morning briefing with consensus shifts and rating changes - ready to review`],generatingSteps:[`Visiting {url} to extract your stock tickers and watchlist details`,`Designing an agent to monitor analyst ratings across 12 major firms daily`,`Configuring upgrade and downgrade detection with price target tracking`,`Setting up daily morning alerts with consensus shifts and rating summaries`],featureSectionTitle:`From tickers to morning briefing`,featureCardTitles:[`Connects to your investing stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Slack, Google Sheets, Notion - Computer plugs into your tools so alerts, trackers, and reports land exactly where you need them.`,`Daily morning briefings. Upgrade and downgrade alerts with rationale. Price target change logs. Consensus shift summaries. Computer delivers analysis you can trade on.`],capabilitySectionTitle:`Your analyst desk, on autopilot`,capabilitySectionSubtitle:`Enter your tickers, step away, wake up to a complete morning briefing.`,capabilityCards:[{title:`Rating Tracking`,description:`Computer can monitor analyst ratings from Goldman Sachs, Morgan Stanley, and 10 other major firms - flagging every upgrade and downgrade as they happen.`},{title:`Price Target Analysis`,description:`Computer can track price target changes across firms, calculate consensus shifts, and highlight the biggest movers on your watchlist.`},{title:`Morning Briefings`,description:`Computer can compile a daily summary with rating changes, rationale, price target moves, and consensus trends - formatted and ready before market open.`},{title:`Connect Your Tools`,description:`Computer can send alerts to Gmail, Slack, Google Sheets, Notion, and more - build workflows that deliver insights wherever you work.`},{title:`Remember & Learn`,description:`Computer can remember your watchlist, preferred firms, and alert thresholds across sessions - so every briefing gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can watch for significant rating changes in real time and ping you when a major firm upgrades or downgrades a position you hold.`}]});export{t as default};
